    const hipblasStatus_t vs=hipblasLtGetVersion(lt,&version);
    if(vs!=HIPBLAS_STATUS_SUCCESS){std::fprintf(stderr,"hipblasLtGetVersion failed: %d\n",(int)vs);return 2;}
    const std::string arch=arch_name(prop.gcnArchName);
