            const double d = std::fabs(ref - y[(size_t) r * N + n]);
            if (!std::isfinite(y[(size_t) r * N + n])) return INFINITY;
            maxabs = std::max(maxabs, std::fabs(ref)); maxdiff = std::max(maxdiff, d);
