                        for (size_t j = j0; j < j1; ++j) padded_total += (L.cnt[L.order[j]] + J - 1) / J * J - L.cnt[L.order[j]];
                    }
                    HIP_CHECK(hipMemcpy(dbounds, bounds.data(), bounds.size() * 4, hipMemcpyHostToDevice));
