                    // note: the engine's gate/up rows per expert are contiguous in id order; a sorted order makes a
                    // group's experts non-contiguous, which the kernel reads through the per-expert bounds anyway.
                    // Here each group's bounds are n_g + 1 consecutive entries (bounds[j] of its experts, then the end).
                    const float ms = time_ms(s, 5, [&] {
                        size_t bi = 0;
