                            p.expert_bytes = eb; p.n = (int) ngx; p.xq = dxq; p.bounds = dbounds + bi; p.ids = dids;
                            p.total_rows = flop_rows; p.max_rows = maxr[g]; p.dst = dy; p.ld_dst = sh.rows;
                            ctx.run(p, s);
