        std::vector<float> x((size_t) flop_rows * sh.cols);
        for (auto& v : x) v = (rng() / 4294967296.0f - 0.5f);
        float* dx; HIP_CHECK(hipMalloc(&dx, x.size() * 4)); HIP_CHECK(hipMemcpy(dx, x.data(), x.size() * 4, hipMemcpyHostToDevice));
