// the layer's row count per expert id: Zipf-like over ranks, the ranks shuffled over the ids
std::vector<int> layer_counts(unsigned seed) {
    std::vector<double> z(NE);
    double s = 0;
    for (int i = 0; i < NE; ++i) { z[i] = std::pow(i + 1.0, -0.8); s += z[i]; }
