    for (int e = 0; e < NE; ++e) if (L.cnt[e] > 0) L.order.push_back(e);
    if (sorted) std::stable_sort(L.order.begin(), L.order.end(), [&](int a, int b) { return L.cnt[a] > L.cnt[b]; });
