    maxr = std::max<int64_t>(maxr, cs[i - j0]);
    sumr += cs[i - j0];
}
std::sort(cs, cs + ngx);
const int64_t optr = opt_mode == 2 ? cs[ngx / 2] : opt_mode == 1 ? (sumr + ngx - 1) / ngx : maxr;

